class TestIsDeprecated:
    @pytest.mark.parametrize('description', ['~~removed~~', '  ~~gone~~  ', '~~two\nlines~~', '~~~~~', '~~x~~\n'])
    def test_strikethrough_is_deprecated(self, description): assert cat.is_deprecated(description)
    @pytest.mark.parametrize('description', ['', 'plain', '~~only start', 'only end~~', '~~~', '~~~~', '~~ ~~', '~~  ~~'])
    def test_everything_else_stays_active(self, description): assert not cat.is_deprecated(description)
    def test_the_rule_is_defined_exactly_once(self):
        root = Path(__file__).resolve().parents[2]; pattern = re.compile('^_?is_deprecated(_description)?$'); scanned = 0; defs: list[tuple[str, str]] = []
        for base in ('common', 'tools'):
            for path in sorted((root / base).rglob('*.py')): scanned += 1; tree = ast.parse(path.read_text(encoding='utf-8')); defs.extend(((path.relative_to(root).as_posix(), node.name) for node in ast.walk(tree) if isinstance(node, ast.FunctionDef) and pattern.match(node.name)))
        assert scanned > 100, f'census scanned only {scanned} files'; assert defs == [('common/testing/check_ac_traceability.py', 'is_deprecated')]
