    def test_placeholder_and_stub_refs_do_not_count_as_real_coverage(self): 'AC-testing.acgates.4 AC8.13.35'; acs = [self._make_ac('AC1.1.1'), self._make_ac('AC1.1.2'), self._make_ac('AC1.1.3')]; refs = {'AC1.1.1': cat.ACReferenceStats(placeholder_files={'placeholder.test.ts'}), 'AC1.1.2': cat.ACReferenceStats(stub_files={'_ac_stubs/test_stub.py'})}; result = cat.check_traceability(acs, refs); assert result.covered == []; assert result.placeholder_only == ['AC1.1.1']; assert result.stub_only == ['AC1.1.2']; assert result.missing == ['AC1.1.3']; 'AC8.13.78'; 'AC8.13.78'; _m6_acs = [self._make_ac('AC1.1.1')]; _m6_refs = {'AC1.1.1': cat.ACReferenceStats(real_files={'tools/tier2_http_e2e.py'})}; _m6_result = cat.check_traceability(_m6_acs, _m6_refs); assert _m6_result.covered == []; assert _m6_result.unexecuted_only == ['AC1.1.1']; assert _m6_result.missing == []
